def solve(matrix):
    if not matrix:
        return 1
    n = len(matrix)
    # Degenerate "empty" rows (e.g. [[]]) -> treat as empty matrix
    if all(len(row) == 0 for row in matrix):
        return 1

    all_ints = all(isinstance(x, int) for row in matrix for x in row)

    if all_ints:
        # Bareiss fraction-free elimination: exact integer arithmetic
        a = [row[:] for row in matrix]
        sign = 1
        prev = 1
        for k in range(n - 1):
            if a[k][k] == 0:
                pivot_row = None
                for i in range(k + 1, n):
                    if a[i][k] != 0:
                        pivot_row = i
                        break
                if pivot_row is None:
                    return 0
                a[k], a[pivot_row] = a[pivot_row], a[k]
                sign = -sign
            for i in range(k + 1, n):
                for j in range(k + 1, n):
                    a[i][j] = (a[i][j] * a[k][k] - a[i][k] * a[k][j]) // prev
                a[i][k] = 0
            prev = a[k][k]
        return sign * a[n - 1][n - 1]

    # Fallback: exact rational elimination (handles non-int inputs)
    a = [[Fraction(str(x)) for x in row] for row in matrix]
