def solve(n):
    if n <= 2:
        return []
    sieve = bytearray(b'1') * n
    sieve[0:2] = b'00'
    import math
    limit = int(math.isqrt(n - 1)) + 1
    for p in range(2, limit):
        if sieve[p]:
            step = p
            start = p*p
            sieve[start:n:step] = b'0' * ((n - 1 - start)//step + 1)
    return [i for i in range(n) if sieve[i]]

