def solve(n, edges):
    # Build adjacency list and indegree counts
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    # Use a min-heap to always pick smallest available node
    import heapq
    heap = [i for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    if len(order) != n:
        return []  # cycle detected
    return order

